<?php
declare(strict_types=1);
require dirname(__DIR__).'/includes/bootstrap.php';require_once dirname(__DIR__).'/includes/incentive.php';
$user=require_staff();$canManage=$user['role_slug']==='administrator';$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!$canManage){http_response_code(403);$errors[]='Administrator access is required to process incentives.';}elseif(!valid_csrf()){http_response_code(403);$errors[]='The form expired. Reload and try again.';}else try{phase6_process_incentive($pdo,(int)post_id('surrender_id'),(int)$user['id']);flash('success','Incentive was calculated and added to the distribution queue.');redirect('admin/incentives.php');}catch(Phase6ValidationException|Phase6ConflictException$e){$errors[]=$e->getMessage();}}
$statuses=['CALCULATED','APPROVED_FOR_DISTRIBUTION','DISTRIBUTED','CANCELLED'];$status=strtoupper(trim((string)($_GET['status']??'')));$search=trim((string)($_GET['q']??''));$siteId=filter_input(INPUT_GET,'establishment_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;$processorId=filter_input(INPUT_GET,'processor_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;$riceUnit=(string)($_GET['rice_unit']??'');$from=(string)($_GET['date_from']??'');$to=(string)($_GET['date_to']??'');$where=[];$params=[];if(in_array($status,$statuses,true)){$where[]='it.status=?';$params[]=$status;}else$status='';if($siteId){$where[]='it.establishment_id=?';$params[]=$siteId;}if($processorId){$where[]='it.calculated_by=?';$params[]=$processorId;}if(in_array($riceUnit,['kg','g'],true)){$where[]='it.rice_unit=?';$params[]=$riceUnit;}else$riceUnit='';if(preg_match('/^\d{4}-\d{2}-\d{2}$/D',$from)){$where[]='it.processed_at>=?';$params[]=$from.' 00:00:00';}else$from='';if(preg_match('/^\d{4}-\d{2}-\d{2}$/D',$to)){$where[]='it.processed_at<?';$params[]=gmdate('Y-m-d',strtotime($to.' +1 day')).' 00:00:00';}else$to='';if($search!==''){$where[]='(it.transaction_code LIKE ? OR os.transaction_code LIKE ? OR e.business_name LIKE ? OR e.owner_name LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like,$like);}$sqlWhere=$where?'WHERE '.implode(' AND ',$where):'';
$q=$pdo->prepare("SELECT it.*,os.transaction_code surrender_code,e.business_name,e.owner_name,u.full_name processor_name FROM incentive_transactions it JOIN oil_surrenders os ON os.id=it.oil_surrender_id JOIN establishments e ON e.id=it.establishment_id JOIN users u ON u.id=it.calculated_by $sqlWhere ORDER BY it.processed_at DESC,it.id DESC LIMIT 500");$q->execute($params);$transactions=$q->fetchAll();
$eligible=$pdo->query("SELECT os.id,os.transaction_code,os.oil_quantity,os.oil_unit,os.approved_at,e.business_name,e.owner_name FROM oil_surrenders os JOIN establishments e ON e.id=os.establishment_id LEFT JOIN incentive_transactions it ON it.oil_surrender_id=os.id WHERE os.status='APPROVED' AND it.id IS NULL ORDER BY os.approved_at,os.id LIMIT 200")->fetchAll();foreach($eligible as &$row){try{$row['rule']=phase6_applicable_rule($pdo,(float)$row['oil_quantity'],$row['oil_unit']);}catch(Phase6ConflictException){$row['rule']=null;$row['rule_error']='Conflicting active rules';}}unset($row);
$counts=$pdo->query("SELECT status,COUNT(*) total FROM incentive_transactions GROUP BY status")->fetchAll(PDO::FETCH_KEY_PAIR);$sites=$pdo->query('SELECT id,business_name FROM establishments ORDER BY business_name')->fetchAll();$processors=$pdo->query("SELECT u.id,u.full_name FROM users u JOIN roles r ON r.id=u.role_id WHERE r.slug IN ('administrator','environmental_staff') ORDER BY u.full_name")->fetchAll();$pageTitle='Incentives';$activeNav='incentives';$flash=consume_flash();require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-heading"><div><div class="breadcrumb">Operations <span>/</span> Incentives</div><h1>Sana Oil incentive processing</h1><p>Only approved oil surrenders can enter the configured reward workflow.</p></div><?php if($canManage): ?><a class="button button-secondary" href="<?= e(url('admin/incentive-rules.php')) ?>">Manage rules</a><?php endif; ?></div>
<?php if($flash): ?><div class="notice notice-<?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><?php foreach($errors as$error): ?><div class="notice notice-error"><?= e($error) ?></div><?php endforeach; ?>
<section class="stat-grid compact-stats"><?php foreach([['Awaiting processing',count($eligible),'sand'],['Pending distribution',(int)($counts['CALCULATED']??0)+(int)($counts['APPROVED_FOR_DISTRIBUTION']??0),'blue'],['Distributed',(int)($counts['DISTRIBUTED']??0),'mint'],['Cancelled',(int)($counts['CANCELLED']??0),'rose']]as[$label,$value,$color]): ?><article class="stat-card"><span class="feature-icon <?= e($color) ?>"><?= icon('gift') ?></span><div><strong><?= $value ?></strong><span><?= e($label) ?></span></div></article><?php endforeach; ?></section>
<section class="panel section-panel"><div class="panel-heading"><div><h2>Approved surrenders awaiting incentive</h2><p>No reward is calculated until an administrator processes the record.</p></div></div><div class="table-scroll"><table><thead><tr><th>Surrender</th><th>Establishment</th><th>Quantity</th><th>Approved</th><th>Applicable rule</th><th>Action</th></tr></thead><tbody><?php foreach($eligible as$row): ?><tr><td><?= e($row['transaction_code']) ?></td><td><?= e($row['business_name']) ?></td><td><?= e(number_format((float)$row['oil_quantity'],3).' '.$row['oil_unit']) ?></td><td><?= $row['approved_at']?e(display_date($row['approved_at'])):'Not recorded' ?></td><td><?= $row['rule']?e($row['rule']['name'].' · '.number_format((float)$row['rule']['rice_reward_quantity'],3).' '.$row['rule']['rice_unit']):'No active incentive rule applies to this surrender.' ?></td><td><?php if($canManage&&$row['rule']): ?><form method="post" data-confirm="Process this approved surrender using the displayed rule?"><?= csrf_field() ?><input type="hidden" name="surrender_id" value="<?= (int)$row['id'] ?>"><button class="button button-primary button-small" type="submit">Process incentive</button></form><?php else: ?><span class="muted"><?= $canManage?'Configure rule':'Read only' ?></span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$eligible): ?><tr><td colspan="6" class="empty-state">No approved surrender is awaiting incentive processing.</td></tr><?php endif; ?></tbody></table></div></section>
<form method="get" class="panel filter-panel"><div class="form-grid"><label class="form-field"><span>Search</span><input name="q" value="<?= e($search) ?>" placeholder="Incentive, surrender, business, owner"></label><label class="form-field"><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach($statuses as$value): ?><option value="<?= e($value) ?>"<?= selected($status,$value) ?>><?= e(str_replace('_',' ',$value)) ?></option><?php endforeach; ?></select></label><label class="form-field"><span>Establishment</span><select name="establishment_id"><option value="">All establishments</option><?php foreach($sites as$site): ?><option value="<?= (int)$site['id'] ?>"<?= selected($siteId,$site['id']) ?>><?= e($site['business_name']) ?></option><?php endforeach; ?></select></label><label class="form-field"><span>Processor</span><select name="processor_id"><option value="">All processors</option><?php foreach($processors as$p): ?><option value="<?= (int)$p['id'] ?>"<?= selected($processorId,$p['id']) ?>><?= e($p['full_name']) ?></option><?php endforeach; ?></select></label><label class="form-field"><span>Rice unit</span><select name="rice_unit"><option value="">All units</option><option value="kg"<?= selected($riceUnit,'kg') ?>>kg</option><option value="g"<?= selected($riceUnit,'g') ?>>g</option></select></label><label class="form-field"><span>From</span><input type="date" name="date_from" value="<?= e($from) ?>"></label><label class="form-field"><span>To</span><input type="date" name="date_to" value="<?= e($to) ?>"></label></div><div class="form-actions"><button class="button button-primary">Apply filters</button><a class="button button-secondary" href="<?= e(url('admin/incentives.php')) ?>">Clear</a></div></form>
<section class="panel section-panel"><div class="panel-heading"><h2>Incentive transactions</h2></div><div class="table-scroll"><table><thead><tr><th>Incentive</th><th>Surrender</th><th>Establishment</th><th>Oil</th><th>Applied rule</th><th>Rice reward</th><th>Status</th><th>Processed</th><th>Distributed</th><th>Action</th></tr></thead><tbody><?php foreach($transactions as$row): ?><tr><td><?= e($row['transaction_code']) ?></td><td><?= e($row['surrender_code']) ?></td><td><?= e($row['business_name']) ?></td><td><?= e(number_format((float)$row['oil_quantity'],3).' '.$row['oil_unit']) ?></td><td><?= e($row['rule_name_snapshot']) ?></td><td><?= e(number_format((float)$row['rice_quantity'],3).' '.$row['rice_unit']) ?></td><td><span class="status-badge status-<?= e(strtolower(str_replace('_','-',$row['status']))) ?>"><?= e(str_replace('_',' ',$row['status'])) ?></span></td><td><?= e(display_date($row['processed_at'])) ?></td><td><?= $row['distributed_at']?e(display_date($row['distributed_at'])):'Pending' ?></td><td><a class="table-action" href="<?= e(url('admin/incentive-view.php?id='.(int)$row['id'])) ?>">View</a></td></tr><?php endforeach; ?><?php if(!$transactions): ?><tr><td colspan="10" class="empty-state">No incentive transactions match these filters.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
